test_spec:
{
  "test_specification": {
    "feature": "consolidate-phase-execution",
    "description": "Test specification for consolidating phase execution in phases.py",

    "section_1_behaviors_that_must_be_verified": {
      "phase_config_registry": {
        "description": "PHASE_CONFIG dictionary must contain all 8 phases with correct configuration",
        "success_criteria": [
          "All 8 phase keys exist: planning, reviewing_plan, spec_impl, spec_test, implementing, fix_feedback, writing_tests, review_impl",
          "Each phase has required keys: runner_phase, history_tag, status_label, template, done_marker",
          "history_tag values contain only alphabetic characters (validation at module load)",
          "done_marker values are correctly set (DONE or TESTDONE)"
        ],
        "expected_outputs": [
          "Module imports without errors",
          "Assertion validation passes for all history_tags"
        ]
      },
      "build_prompt_helper": {
        "description": "_build_prompt() must load templates and apply variable substitutions",
        "success_criteria": [
          "Template file is loaded from PROMPTS_DIR",
          "All key-value replacements in the dict are applied via .replace()",
          "FileNotFoundError is raised when template doesn't exist",
          "Complete modified template string is returned"
        ],
        "expected_outputs": [
          "Returns populated template string with all {placeholder} values replaced"
        ]
      },
      "run_phase_helper": {
        "description": "_run_phase() must execute common execution pattern for all phases",
        "success_criteria": [
          "Status is updated when status parameter is not None",
          "History is added with correct history_tag and message",
          "Feature is saved after history update (unless skip_history_start=True)",
          "runner.headless() is called with correct prompt and status",
          "Error handling catches headless() failures and records them in history",
          "RuntimeError is raised when output is empty or whitespace only",
          "skip_history_start flag prevents double-logging for sub-phases"
        ],
        "expected_outputs": [
          "Returns raw output string from runner.headless()",
          "On failure: error logged to history before re-raising exception"
        ]
      },
      "parse_verdict_helper": {
        "description": "_parse_verdict() must parse verdict and feedback from review output",
        "success_criteria": [
          "JSON format with verdict key is parsed correctly",
          "Text format with VERDICT: prefix is parsed correctly",
          "Feedback is extracted from JSON 'feedback' key or FEEDBACK: text marker",
          "Markdown formatting is stripped from feedback",
          "Returns tuple of (verdict, feedback) where verdict is 'PASS' or 'FAIL'",
          "Fallback to text parsing when JSON parsing fails"
        ],
        "expected_outputs": [
          "Returns ('PASS', feedback) when verdict contains 'PASS'",
          "Returns ('FAIL', feedback) otherwise"
        ]
      },
      "phase_function_refactoring": {
        "run_planning": {
          "description": "run_planning must use _build_prompt() but remain mostly custom",
          "success_criteria": [
            "Uses _build_prompt() for template loading",
            "Retains unique JSON parsing for questions/plan",
            "Retains completion marker stripping logic"
          ]
        },
        "run_reviewing_plan": {
          "description": "run_plan_review must use _parse_verdict()",
          "success_criteria": [
            "Calls _parse_verdict() to extract verdict and feedback",
            "Updates feature with parsed verdict and feedback"
          ]
        },
        "run_spec_writing": {
          "description": "run_spec_writing must handle two sub-phases",
          "success_criteria": [
            "First sub-call uses _run_phase('spec_impl', ...) with skip_history_start=False",
            "Second sub-call uses _run_phase('spec_test', ...) with skip_history_start=True",
            "Does not double-log history entries"
          ]
        },
        "run_implementing": {
          "description": "run_implementing must use _build_prompt() and _run_phase()",
          "success_criteria": [
            "Calls _build_prompt('implement.md', replacements)",
            "Calls _run_phase('implementing', feature, runner, prompt, status)",
            "Appends previous feedback to prompt if available",
            "Sets impl_notes, adds history, saves feature, moves to testing stage, commits, deletes checkpoint"
          ]
        },
        "run_fix_feedback": {
          "description": "run_fix_feedback must use _build_prompt() and _run_phase()",
          "success_criteria": [
            "Calls _build_prompt('fix-feedback.md', replacements)",
            "Calls _run_phase('fix_feedback', feature, runner, prompt, status)"
          ]
        },
        "run_writing_tests": {
          "description": "run_writing_tests must use _build_prompt() and _run_phase()",
          "success_criteria": [
            "Calls _build_prompt('write-tests.md', replacements)",
            "Calls _run_phase('writing_tests', feature, runner, prompt, status)"
          ]
        },
        "run_review_impl": {
          "description": "run_review_impl must use _parse_verdict()",
          "success_criteria": [
            "Calls _parse_verdict() to extract verdict and feedback",
            "Updates feature with parsed verdict and feedback"
          ]
        }
      },
      "checkpoint_template_extraction": {
        "description": "Checkpoint instruction blocks must be consolidated into shared template",
        "success_criteria": [
          "_checkpoint-instructions.md file exists in pipeline/prompts/",
          "Contains the 20-line checkpoint instruction block with placeholders",
          "Prompt templates contain {checkpoint_instructions} marker",
          "_build_prompt() automatically injects checkpoint block when marker present",
          "{done_marker} placeholder is replaced with correct value from PHASE_CONFIG"
        ],
        "expected_outputs": [
          "test-spec.md uses 'TESTDONE' as done marker",
          "Other templates use 'DONE' as done marker"
        ]
      }
    },

    "section_2_edge_cases": {
      "empty_null_inputs": {
        "description": "System must handle empty or null inputs gracefully",
        "test_cases": [
          {
            "input": "feature.plan is None or empty string",
            "expected_behavior": "_build_prompt() replacements should use '(no plan)' as fallback"
          },
          {
            "input": "feature.impl_spec is None or empty string",
            "expected_behavior": "_build_prompt() replacements should use '(no impl spec)' as fallback"
          },
          {
            "input": "feature.test_spec is None or empty string",
            "expected_behavior": "_build_prompt() replacements should use '(no test spec)' as fallback"
          },
          {
            "input": "status parameter is None",
            "expected_behavior": "_run_phase() should skip status updates (guard: if status is not None)"
          },
          {
            "input": "start_message is empty/not provided",
            "expected_behavior": "Default message should be generated from history_tag"
          }
        ]
      },
      "boundary_conditions": {
        "description": "System must handle boundary conditions",
        "test_cases": [
          {
            "input": "replacements dict is empty",
            "expected_behavior": "Template should be returned without modifications"
          },
          {
            "input": "replacement value contains the placeholder itself (circular)",
            "expected_behavior": "Single pass replacement - may result in placeholder remaining"
          },
          {
            "input": "Very long feature title or plan",
            "expected_behavior": "Should be inserted without truncation"
          }
        ]
      },
      "invalid_states": {
        "description": "System must handle invalid states",
        "test_cases": [
          {
            "input": "Template file doesn't exist",
            "expected_behavior": "_build_prompt() raises FileNotFoundError with clear message"
          },
          {
            "input": "PHASE_CONFIG has invalid history_tag (non-alphabetic)",
            "expected_behavior": "Module-load assertion fails with error message"
          },
          {
            "input": "Invalid phase_key passed to _run_phase()",
            "expected_behavior": "KeyError raised when accessing PHASE_CONFIG[phase_key]"
          }
        ]
      },
      "error_conditions": {
        "description": "System must handle error conditions gracefully",
        "test_cases": [
          {
            "input": "runner.headless() throws exception",
            "expected_behavior": "Exception caught, error logged to history, exception re-raised"
          },
          {
            "input": "runner.headless() returns empty string",
            "expected_behavior": "RuntimeError raised with message about empty output"
          },
          {
            "input": "runner.headless() returns whitespace only",
            "expected_behavior": "RuntimeError raised (output.strip() is empty)"
          },
          {
            "input": "JSON in output is malformed",
            "expected_behavior": "_parse_verdict() falls back to text parsing"
          },
          {
            "input": "Output has no VERDICT marker at all",
            "expected_behavior": "_parse_verdict() returns FAIL with full output as feedback"
          }
        ]
      },
      "concurrent_operations": {
        "description": "System must handle concurrent operations appropriately",
        "test_cases": [
          {
            "scenario": "Two phase functions running on same feature",
            "expected_behavior": "Each call to _run_phase() adds separate history entry with timestamps"
          },
          {
            "scenario": "feature.save() called while previous save in progress",
            "expected_behavior": "File I/O is sequential - no locking mechanism needed (Python GIL)"
          }
        ]
      }
    },

    "section_3_what_constitutes_failure": {
      "criteria_for_test_failure": [
        "Import error when importing phases module",
        "AssertionError during module load (invalid history_tag)",
        "FileNotFoundError when loading non-existent template",
        "RuntimeError when headless() returns empty output",
        "KeyError when accessing non-existent PHASE_CONFIG key",
        "ValueError when verdict parsing fails to return valid tuple"
      ],
      "error_messages_expected": [
        "Prompt template not found: {path}",
        "Invalid history_tag in PHASE_CONFIG",
        "Phase {phase_key} produced empty output for {feature.title}",
        "{phase_key} headless() failed for {feature.title}: {error_details}"
      ],
      "rollback_behavior": [
        "Each commit is independently revertable",
        "If commit 4 causes issues, commits 1-3 remain valid",
        "Feature plan documents 5 incremental commits for safe rollback",
        "No database migrations or persistent state changes required"
      ]
    },

    "section_4_out_of_scope": {
      "explicitly_not_testing": [
        "UI timing - response time of web interfaces (none exist)",
        "Visual assertions - screenshot comparisons",
        "Performance benchmarks - execution speed measurements",
        "Network latency - actual LLM API response times",
        "Memory profiling - memory usage during execution",
        "Concurrency stress testing - high-volume parallel execution",
        "Long-running stability - multi-hour continuous operation",
        "File system race conditions - concurrent file access beyond Python GIL",
        "Agent-specific behavior - internal logic of AgentRunner or agents",
        "Prompt content quality - whether LLM responses are 'good' or 'correct'",
        "Git operation details - internal git implementation beyond _git_commit()",
        "External API failures - network unreachable scenarios beyond error handling"
      ],
      "rationale": [
        "This is a refactoring task - the goal is to consolidate duplicated code, not change behavior",
        "Existing tests (if any) should continue to pass",
        "The refactoring should be transparent to end users",
        "Performance is not a concern for this code consolidation"
      ]
    },

    "testing_strategy_recommendations": {
      "per_commit_validation": {
        "commit_1": [
          "Run: python -c 'import phases' - verify no import errors",
          "Verify PHASE_CONFIG dictionary has all 8 phases",
          "Verify _build_prompt() raises FileNotFoundError for missing template",
          "Verify _parse_verdict() returns correct tuple for JSON and text formats"
        ],
        "commit_2": [
          "All of commit 1 tests",
          "Verify _run_phase() function exists and has correct signature"
        ],
        "commit_3": [
          "All of commit 1-2 tests",
          "Verify run_plan_review and run_review_impl use _parse_verdict()"
        ],
        "commit_4": [
          "All of commit 1-3 tests",
          "Run full test suite if present",
          "Quick pipeline test on dummy feature to verify end-to-end behavior preserved"
        ],
        "commit_5": [
          "All of commit 1-4 tests",
          "Verify _checkpoint-instructions.md exists",
          "Verify all 6 templates contain {checkpoint_instructions} marker",
          "Verify test-spec.md contains TESTDONE"
        ]
      },
      "integration_test_notes": [
        "Full integration testing requires actual AgentRunner and feature files",
        "Mock/stub testing is sufficient for unit validation",
        "The refactoring should not change any external interfaces"
      ]
    }
  }
}

